def icon_svg(
    name: str,
    size: int = 16,
    color: str = "currentColor",
    stroke: float = 1.8,
    extra_class: str = "",
) -> str:
    """
    Returns an inline SVG string for the specified icon name.
    Falls back to a circle if icon name is unknown.
    """
    template = ICON_SVGS.get(name)
    if not template:
        template = """<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round" class="{cls}"><circle cx="12" cy="12" r="8"></circle></svg>"""
    
    return template.format(
        size=size,
        color=color,
        stroke=stroke,
        cls=extra_class,
    )


def icon_with_text(
    name: str,
    text: str,
    size: int = 15,
    color: str = "currentColor",
    gap: str = "6px",
    extra_style: str = "",
) -> str:
    """Helper to render an icon with text aligned in a flex row."""
    svg = icon_svg(name, size=size, color=color)
    return f"""<span style="display: inline-flex; align-items: center; gap: {gap}; {extra_style}">{svg} <span>{text}</span></span>"""
